"},"revision":{"type":"integer","minimum":1,"maximum":1000000,"description":"The revision of this notification. A recipient replaces the record it holds with a higher revision and leaves it unchanged for an equal or lower one (VTI-NTF-022). The first revision is 1."},"kind":{"\$ref":"#/\$defs/Kind"},"subject":{"\$ref":"#/\$defs/Subject"},"audience":{"\$ref":"#/\$defs/Did","description":"The DID whose holders or members the thing concerns — for an election under a credential roll, the DID the roll names (`roll.memberOf`); otherwise the community\'s own. It says whom the thing is for, not that the recipient is one of them: a recipient may be the audience itself, or a party the audience relayed the notification to."},"status":{"\$ref":"#/\$defs/Status"},"relayable":{"type":"boolean","description":"Whether the addressee may relay this notification to the parties it stands for (notifications/relay). The originator states it explicitly; an addressee MUST NOT relay a notification whose `relayable` is false, or whose kind may not be relayed (VTI-NTF-041)."},"validFrom":{"type":"string","format":"date-time","description":"When the thing can first be acted on — for an election, when voting opens. Absent: it can be acted on now."},"validUntil":{"type":"string","format":"date-time","description":"When the thing can no longer be acted on, and the notification lapses — for an election, when voting closes. A recipient discards a notification received after it (VTI-NTF-032). Absent: the kind\'s definition says when it lapses."}}},"Status":{"title":"Status","description":"Whether the thing is still open to the audience: `available`, or `withdrawn` — cancelled by its holder, or no longer open to the audience — in which case the recipient keeps the record only to show that it was withdrawn (VTI-NTF-024).","type":"string","enum":["available","withdrawn"]},"Did":{"title":"Did","description":"A DID.","type":"string","minLength":8,"maxLength":2048,"pattern":"^did:[a-z0-9]+:\\\\S+\$"},"Subject":{"title":"Subject","description":"Where the thing is and how to open it. Only these three members: what the thing contains is shown by its holder, to a reader it admits, when the thing is opened with `openWith`.","type":"object","additionalProperties":false,"required":["heldBy","id","openWith"],"properties":{"heldBy":{"\$ref":"#/\$defs/Did","description":"The DID of the party holding the thing — for an election, the community. The party a recipient sends `openWith` to."},"id":{"type":"string","minLength":1,"maxLength":256,"description":"The thing\'s identifier at `heldBy`, in the form the `openWith` task takes it — for an election, its `electionId`."},"openWith":{"type":"string","minLength":1,"maxLength":512,"pattern":"^https://\\\\S+\$","description":"The Type URI of the Trust Task by which a recipient opens the thing at `heldBy` — for an election, `https://trusttasks.org/spec/vtc/elections/show/0.6`. A recipient opens it only at its principal\'s choice (VTI-NTF-053), and only by a version of that task it and `heldBy` both serve."}}},"Kind":{"title":"Kind","description":"What the thing is. Either a registered kind — one lowerCamelCase name in the VTI specification\'s notification kind registry (Appendix G), such as `election` — or an unregistered kind, written `<reverse-DNS domain>:<name>` under a domain its definer controls, such as `org.example:meetingInvite`. A recipient that does not recognise a kind holds, lists and discards it and does nothing else with it (VTI-NTF-012).","type":"string","minLength":1,"maxLength":256,"pattern":"^([a-z][a-zA-Z0-9]{0,63}|[a-z0-9]+(-[a-z0-9]+)*(\\\\.[a-z0-9]+(-[a-z0-9]+)*)+:[a-z][a-zA-Z0-9]{0,63})\$"},"NotificationId":{"title":"NotificationId","description":"The originator\'s identifier for one notification, unique among the notifications that originator issues and the same in every document that carries it — retries, re-issued documents and relayed copies alike. It is the notification\'s idempotency key (VTI-NTF-021). Compared for equality only. An originator SHOULD make it unguessable and SHOULD NOT make it descriptive: it travels as far as the notification does.","type":"string","minLength":1,"maxLength":256,"pattern":"^[A-Za-z0-9._~:-]+\$"},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: false,
  isRecipientRequired: true,
  isIssuedAtRequired: false,
  payloadSchema: responsePayloadSchemaJson,
);
